-- v992: контент курса «Адаптация» — День 7 · Экзамен и допуск. Сгенерировано gen-academy-adaptation.mjs

INSERT INTO academy_modules (id, course_id, sort, title, intro, gate, active) VALUES
 ($sd$a0000000-0000-0000-0002-000000000007$sd$, $sd$c0000000-0000-0000-0000-000000000002$sd$, 80, $sd$День 7 · Экзамен и допуск$sd$, $sd$Тест по продукту здесь, в платформе. Большая ролёвка и проверка CRM — с наставником. Решение: допуск к работе или 2 дня доработки.$sd$, $sd${"title":"Экзамен и допуск","tasks":["Тест по продукту сдан на 10 / 10 (урок выше)","Устный тест по 5П с наставником","Большая ролёвка: лид → квалификация → закрытие на демо → мини-демо → работа с возражением","Практика CRM: корректность заполнения полей на тестовой сделке проверена по чек-листу","Проверка цепочки касаний: написал 5 сообщений"],"result":"Решение наставника: допуск к работе — или 2 дня доработки по слабым зонам."}$sd$::jsonb, true)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, sort = EXCLUDED.sort, title = EXCLUDED.title, intro = EXCLUDED.intro, gate = EXCLUDED.gate, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000701$sd$, $sd$a0000000-0000-0000-0002-000000000007$sd$, 10, $sd$Экзамен: тест по продукту$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"1.1 Какую ключевую проблему клиента решает продукт?","options":["Бухгалтерский учёт","Операционные разрывы между агентами, логистами и руководителями; потеря заявок; неэффективная логистика; отсутствие прозрачности","Подбор персонала","Маркетинг и реклама"],"correct":1},{"q":"1.2 Три целевых сегмента:","options":["Ритейл, HoReCa, e-commerce","A — крупный, B — средний, C — малый бизнес","Производители, импортёры, банки","Казахстан, Кыргызстан, Узбекистан"],"correct":1},{"q":"1.3 Модель лицензирования:","options":["Разовая покупка","SaaS-подписка, $10 за пользователя в месяц","Процент от оборота","Бесплатно с платной поддержкой"],"correct":1},{"q":"1.4 Три основных модуля:","options":["Склад, бухгалтерия, HR","Управление торговыми представителями, логистика, аналитика и отчётность","Сайт, CRM, рассылки","Касса, эквайринг, чеки"],"correct":1},{"q":"1.5 Стандартное внедрение занимает:","options":["1 день","2–3 недели","3–6 месяцев","Год"],"correct":1},{"q":"2.1 Характеристики B-сегмента:","options":["150+ пользователей, долгий цикл","10–50 пользователей, чек $1 000–1 500/год, 83 % выручки, быстрое решение","До 5 пользователей, чек $420","Только Van Sales"],"correct":1},{"q":"2.2 Что входит в базовую лицензию?","options":["Внедрение и интеграция","Неограниченные клиенты, приложение iOS/Android, поддержка 24/7, обновления","Только веб-доступ","Кастомные модули"],"correct":1},{"q":"2.3 Дополнительные услуги:","options":["Внедрение от $1 000; интеграция с 1С/ERP; кастомные модули — индивидуально","Только обучение","Только поддержка","Хостинг и домен"],"correct":0},{"q":"2.4 Четыре этапа внедрения:","options":["Диагностика 3–5 дней → настройка 1–2 нед → пилот 2 нед → полное внедрение 1–2 нед","Договор → оплата → установка → обучение","Демо → КП → счёт → запуск","Аудит → ТЗ → разработка → релиз"],"correct":0},{"q":"2.5 Какие метрики эффективности гарантируем?","options":["+100 % продаж","−40 % время обработки заказов, снижение ошибок до 95 %, −15–20 % логистика","0 возвратов","−50 % штата"],"correct":1}]$sd$::jsonb, $sd$<p>Уровни 1 и 2 из корпоративного теста по продукту: «понимает, что продаёт и кому» и «знает сегменты, цены, модули». <b>Критерий прохода — 10 из 10.</b> Пересдавать можно; наставник видит количество попыток.</p>
<p>Уровень 3 (кейсы, ROI, отстройка) сдаётся устно на ролёвке и для перехода на следующий грейд.</p>$sd$, $sd$[{"t":"Тест по продукту","u":"https://docs.google.com/spreadsheets/d/1Fo-mBEdph1TaSmYjPj4Dts2Ilkj9LZaqH5TWJGt4Rwo/edit"}]$sd$::jsonb, 100, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000702$sd$, $sd$a0000000-0000-0000-0002-000000000007$sd$, 20, $sd$Как оценивают знание скриптов$sd$, $sd$10 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"На каком уровне менеджеру запрещены самостоятельные звонки?","options":["5","3","2","4"],"correct":2},{"q":"Что даёт 5 баллов на экспресс-проверке?","options":["Уровень 3","Уровень 5","Уровень 4","Ничего"],"correct":1},{"q":"Не закрыл на КЭВ — уровень…","options":["Не выше 3","Не выше 4","5","Не оценивается"],"correct":0},{"q":"Как часто проходит полная аттестация по 4 скриптам?","options":["Ежедневно","Еженедельно","Ежемесячно","Раз в год"],"correct":2}]$sd$::jsonb, $sd$<p>Пять уровней. Уровень фиксируется в CRM, от него зависит допуск к звонкам и грейд.</p>
<table class="tbl"><thead><tr><th>Уровень</th><th>Критерий</th><th>KPI</th><th>Действие</th></tr></thead><tbody>
<tr><td><b>5 · Эксперт</b></td><td>Скрипт дословно + адаптация под контекст, предвосхищение, продающие вопросы, доп. модули (2ГИС, геймификация)</td><td>100 %</td><td>Премия, наставничество</td></tr>
<tr><td><b>4 · Мастер</b></td><td>Все блоки, не пропускает этапы, закрывает на КЭВ / сделку, адаптация ограничена</td><td>90 %</td><td>Бонус, право обучать</td></tr>
<tr><td><b>3 · Пользователь</b></td><td>Знает структуру, путает последовательность, пропускает детали (бонусы, гарантию)</td><td>70 %</td><td>Требуется обучение</td></tr>
<tr><td><b>2 · Новичок</b></td><td>Фрагментарно помнит, теряет логику, закрытие «в лоб»</td><td>40 %</td><td>Запрет на самостоятельные звонки</td></tr>
<tr><td><b>1 · Незнание</b></td><td>Не воспроизводит, импровизирует без структуры</td><td>0 %</td><td>Не допускается к продажам</td></tr>
</tbody></table>
<h4>Еженедельная экспресс-проверка РОПа — 5 баллов</h4>
<p>«Представь, я клиент — дистрибьютор, у которого уже есть 1С. Позвони мне.»</p>
<ul class="check"><li>Начал с визитки и интриги (+1)</li><li>Задал квалифицирующие вопросы (+1)</li><li>Предвосхитил «у нас уже всё есть» (+1)</li><li>Закрыл на демо / счёт (+1)</li><li>Использовал «кстати» — 2ГИС / бонус (+1)</li></ul>
<p>5 баллов — уровень 5. 3–4 — уровни 3–4. 0–2 — уровни 1–2. Не задал вопросы из «Прояснения» или не закрыл на КЭВ — не выше уровня 3.</p>
<p><b>Ежемесячная аттестация:</b> полный прогон 4 скриптов — холодный, входящий, закрытие на демо, закрытие после демо. 3 кейса, 15 минут.</p>$sd$, $sd$[{"t":"Оценка знания скриптов","u":"https://docs.google.com/spreadsheets/d/1M6Px1yJd56KYBE1_Y7JvIFbBhoqrNo7YctJaf5TvmOI/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;
